"""Synthetic A1 metric harness; labels are hand-authored, never generated by AI."""
import argparse
from collections import Counter
from datetime import datetime, timezone
import json
import platform
import resource
from statistics import mean
from time import perf_counter

from mcias.agents.invoice_integrity import AGENT_VERSION, RULESET_VERSION, analyze
from tests.a1.synthetic_cases import GOLD, case


def evaluate():
    rows, latencies = [], []
    before = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    for name, expected in GOLD.items():
        b = case(name)
        start = perf_counter()
        actual = analyze(b)  # no model: explicitly rules-only benchmark
        elapsed_ms = 1000 * (perf_counter() - start)
        latencies.append(elapsed_ms)
        rows.append({"case": name, "ground_truth": expected, "predicted": actual["finding_status"],
                     "milliseconds": round(elapsed_ms, 4),
                     "finding_types": [f["finding_type"] for f in actual["findings"]]})
    tp = sum(x["predicted"] == "REVIEW" and x["ground_truth"] == "REVIEW" for x in rows)
    fp = sum(x["predicted"] == "REVIEW" and x["ground_truth"] == "PASS" for x in rows)
    fn = sum(x["predicted"] != "REVIEW" and x["ground_truth"] == "REVIEW" for x in rows)
    tn = sum(x["predicted"] == "PASS" and x["ground_truth"] == "PASS" for x in rows)
    abstain = sum(x["predicted"] == "INSUFFICIENT_EVIDENCE" for x in rows)
    sorted_time = sorted(latencies)
    return {
        "mode": "DETERMINISTIC_ONLY_AI_NOT_EVALUATED", "agent_version": AGENT_VERSION,
        "ruleset_version": RULESET_VERSION, "generated_at": datetime.now(timezone.utc).isoformat(),
        "gold_provenance": "tests/a1/synthetic_cases.py::GOLD (manually specified)",
        "sample_size": len(rows), "TP": tp, "FP": fp, "FN": fn, "TN": tn,
        "abstentions": abstain, "precision": tp/(tp+fp) if tp+fp else None,
        "recall": tp/(tp+fn) if tp+fn else None,
        "latency_ms_mean": round(mean(latencies), 4),
        "latency_ms_p95": round(sorted_time[max(0, int(len(sorted_time)*.95)-1)], 4),
        "peak_rss_kib_os": resource.getrusage(resource.RUSAGE_SELF).ru_maxrss,
        "peak_rss_delta_kib_os": resource.getrusage(resource.RUSAGE_SELF).ru_maxrss-before,
        "platform": platform.platform(), "model_inference_samples": 0,
        "baseline_comparison": "G5 checks aggregate claims/tariffs after institution-approved policy; "
            "not a line-level comparable classifier. No baseline accuracy is claimed.",
        "rows": rows,
    }


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", default="a1-results.json")
    args = parser.parse_args()
    result = evaluate()
    with open(args.output, "w", encoding="utf-8") as fp:
        json.dump(result, fp, ensure_ascii=False, indent=2)
    print(json.dumps({k: v for k, v in result.items() if k != "rows"}, ensure_ascii=False))
